using namespace std;

long long countLucky(long long x, long long limit) {
    if (x > limit) return 0;
    return 1 + countLucky(x * 10 + 4, limit) + countLucky(x * 10 + 7, limit);
}

int main() {
    long long n;
    cin >> n;

    cout << countLucky(4, n) + countLucky(7, n) << "\n";

    return 0;
}

code.java:
import java.util.*;

public class Main {
    static long countLucky(long x, long limit) {
        if (x > limit) return 0;
        return 1 + countLucky(x * 10 + 4, limit) + countLucky(x * 10 + 7, limit);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();

        System.out.println(countLucky(4, n) + countLucky(7, n));
    }
}
